def adoptar_identidad_base(apps, schema_editor):
    """Lleva a la identidad base los campos que nadie personalizó.

    Campo por campo y no el tema entero: si un administrador ya había elegido
    su color de menú, ese se queda, y lo que siga en el valor de la plantilla
    pasa al de la identidad. Comparar sin mayúsculas porque el formulario
    guarda el hexadecimal tal como se escribió.
    """
    SiteTheme = apps.get_model("branding", "SiteTheme")
    for tema in SiteTheme.objects.all():
        cambiados = []
        for campo, anterior in ANTERIORES.items():
            actual = getattr(tema, campo)
            if str(actual).lower() == str(anterior).lower():
                setattr(tema, campo, NUEVOS[campo])
                cambiados.append(campo)
        if cambiados:
            tema.save(update_fields=cambiados)


